package app.noir.mobile;
import android.content.Intent;
import android.view.View;
import org.json.JSONObject;

final class WatchChoice {
 static final java.util.Map<MainActivity,NoirSheet> sheets=new java.util.WeakHashMap<>();
 static {String[][] words={{"How do you want to watch?","كيف تريد المشاهدة؟"},{"Play from your PC","تشغيل من الكمبيوتر"},{"Stream now","البث الآن"},{"Choose a stream…","اختيار بث…"},{"Save to this phone","حفظ على هذا الهاتف"},{"Keep this show ready","إبقاء هذا المسلسل جاهزًا"},{"Always do this on this phone","افعل ذلك دائمًا على هذا الهاتف"},{"Your PC isn't reachable right now","لا يمكن الوصول إلى الكمبيوتر الآن"},{"Pair with your PC first","اقترن بالكمبيوتر أولًا"},{"This video isn't on your PC","هذا الفيديو غير موجود على الكمبيوتر"},{"No streaming source set up","لم يتم إعداد مصدر للبث"},{"No phone download source set up","لم يتم إعداد مصدر لتنزيلات الهاتف"},{"Copy from your PC","نسخ من الكمبيوتر"},{"Use your phone download source","استخدام مصدر تنزيلات الهاتف"},{"Set up streaming","إعداد البث"},{"When a video isn't on this phone","عندما لا يكون الفيديو على هذا الهاتف"},{"Ask every time","السؤال في كل مرة"},{"Play from PC","التشغيل من الكمبيوتر"},{"Stream","البث"}};for(String[] w:words)Loc.AR.put(w[0],w[1]);}
 // "Start over" must survive the trip through stream search; PhoneStream.play turns the marker into the restart extra.
 static JSONObject streamItem(JSONObject item,boolean restart){if(!restart)return item;JSONObject copy=DataStore.copy(item);DataStore.put(copy,"noirRestart",true);return copy;}
 static String preference(android.content.Context c){return BackgroundSync.device(c).getString("watchChoice","");}
 static void preference(android.content.Context c,String value){BackgroundSync.device(c).edit().putString("watchChoice",value.equals("pc")||value.equals("stream")?value:"").apply();}
 static boolean pc(DataStore data,JSONObject item){return data.paired()&&item.optBoolean("available")&&data.online;}
 static void open(MainActivity a,JSONObject item,boolean restart){if(TvUi.isTv(a)||!a.data.localFile(item.optString("id")).isEmpty()){a.playFromPc(item,restart);return;}if(preference(a.data.context).equals("stream")&&PhoneStream.available(a)){PhoneStream.start(a,streamItem(item,restart),false);return;}
  if(a.data.paired()&&item.optBoolean("available")&&!a.data.online){long render=a.renderRevision;DataStore captured=a.data;DataStore.WorkCancel work=new DataStore.WorkCancel();java.util.concurrent.atomic.AtomicBoolean done=new java.util.concurrent.atomic.AtomicBoolean();java.util.concurrent.atomic.AtomicBoolean reachable=new java.util.concurrent.atomic.AtomicBoolean();java.util.concurrent.Future<?>[] task={null};Runnable finish=()->{if(!done.compareAndSet(false,true))return;work.cancel();if(task[0]!=null)task[0].cancel(true);if(!a.active||a.isFinishing()||a.data!=captured||a.renderRevision!=render)return;captured.online=reachable.get();choose(a,item,restart);};a.handler.postDelayed(finish,1900);try{task[0]=PhoneStream.interactive.submit(()->{DataStore.workCancel.set(work);try{try{captured.pcRequest("/v1/changes",null);}catch(DataStore.HttpStatus e){if(e.status!=404)throw e;captured.pcRequest("/v1/library",null);}if(!work.stopped)reachable.set(true);}catch(Exception ignored){}finally{DataStore.workCancel.remove();a.handler.post(finish);}});}catch(java.util.concurrent.RejectedExecutionException e){finish.run();}return;}choose(a,item,restart);
 }
 static void choose(MainActivity a,JSONObject item,boolean restart){String remembered=preference(a.data.context);if(remembered.equals("pc")&&pc(a.data,item)){a.playFromPc(item,restart);return;}if(remembered.equals("stream")&&PhoneStream.available(a)){PhoneStream.start(a,streamItem(item,restart),false);return;}NoirSheet old=sheets.remove(a);if(old!=null)old.dismiss();NoirSheet sheet=sheet(a,item,restart);sheets.put(a,sheet);sheet.dialog.setOnDismissListener(d->{if(sheets.get(a)==sheet)sheets.remove(a);});sheet.show();}
 static NoirSheet sheet(MainActivity a,JSONObject item,boolean restart){String episode=item.optBoolean("movie")?"":String.format(java.util.Locale.ROOT,"S%02d · E%02d",item.optInt("season"),item.optInt("episode"));String subtitle=item.optString("title")+(episode.isEmpty()?"":" · "+(Loc.arabic?"\u2066"+episode+"\u2069":episode));NoirSheet s=new NoirSheet(a,"How do you want to watch?",subtitle);boolean[] always={false};boolean pc=pc(a.data,item),stream=PhoneStream.available(a);String pcReason=!a.data.paired()?"Pair with your PC first":!item.optBoolean("available")?"This video isn't on your PC":"Your PC isn't reachable right now";
  if(a.data.paired()&&item.optBoolean("available"))NoirIcons.row(s,"pc","Play from your PC","",pc,pcReason,()->{if(always[0])preference(a.data.context,"pc");s.dismiss();a.playFromPc(item,restart);});
  View streamRow=NoirIcons.row(s,"play","Stream now","",stream,"No streaming source set up",()->{if(always[0])preference(a.data.context,"stream");s.dismiss();PhoneStream.start(a,streamItem(item,restart),false);});if(!stream)streamRow.setOnClickListener(v->{s.dismiss();a.startActivity(new Intent(a,PhoneDownloadSettingsActivity.class));});
  View picker=NoirIcons.row(s,"list","Choose a stream…","",stream,"No streaming source set up",()->{s.dismiss();PhoneStream.start(a,streamItem(item,restart),true);});if(!stream)picker.setOnClickListener(v->{s.dismiss();a.startActivity(new Intent(a,PhoneDownloadSettingsActivity.class));});
  JSONObject config=PhoneStream.settings(a);boolean provider=!config.optString("manifest").isEmpty();NoirIcons.row(s,"downloads","Save to this phone",pc?"Copy from your PC":"Use your phone download source",pc||provider,!a.data.paired()||!item.optBoolean("available")?"No phone download source set up":"Your PC isn't reachable right now",()->{s.dismiss();if(pc)a.download(item,false);else{a.data.rememberPhoneItem(item);PhoneDownloadsActivity.open(a,item,false);}});
  if(!item.optBoolean("movie"))NoirIcons.row(s,"clock","Keep this show ready","",true,"",()->{s.dismiss();DownloadHubActivity.openKeepReady(a,item.optString("group"));});
  s.check("Always do this on this phone",false,(v,checked)->always[0]=checked);return s;
 }
 static String preferenceLabel(android.content.Context c){String value=preference(c);return Loc.t(value.equals("pc")?"Play from PC":value.equals("stream")?"Stream":"Ask every time");}
 static NoirSheet settings(MainActivity a){NoirSheet s=new NoirSheet(a,"When a video isn't on this phone",null);String[] labels={"Ask every time","Play from PC","Stream"},values={"","pc","stream"};for(int n=0;n<labels.length;n++){final int index=n;NoirIcons.row(s,n==0?"list":n==1?"pc":"play",labels[n],"",true,"",()->{preference(a.data.context,values[index]);s.dismiss();a.renderKeep();});}s.show();return s;}
}
